```python
#!/usr/bin/env python3

import json
import sys
from typing import Any


FIELD_RENAMES = {
    "user_name": "name",
    "user_email": "email",
    "user_age": "age",
}


def coerce_value(key: str, value: Any) -> Any:
    """
    Apply small, safe type normalizations for migrated fields.

    - age: convert numeric strings to int where possible.
    - empty strings for migrated fields become None.
    - name/email remain strings if already strings; otherwise they are preserved.
    """
    if value == "":
        return None

    if key == "age":
        if value is None:
            return None
        if isinstance(value, bool):
            # Avoid treating True/False as 1/0.
            return value
        if isinstance(value, int):
            return value
        if isinstance(value, float):
            # Preserve non-integral floats, but convert 30.0 -> 30.
            return int(value) if value.is_integer() else value
        if isinstance(value, str):
            stripped = value.strip()
            if stripped == "":
                return None
            try:
                return int(stripped)
            except ValueError:
                try:
                    number = float(stripped)
                    return int(number) if number.is_integer() else number
                except ValueError:
                    return value

    return value


def migrate(obj: Any) -> Any:
    """
    Recursively migrate dictionaries/lists by renaming legacy user_* fields.

    Collision policy:
    If both a legacy key and its new key are present in the same object, the
    existing new key is treated as canonical and is not overwritten by the
    legacy key. The legacy key is omitted from the output to complete the schema
    migration.
    """
    if isinstance(obj, list):
        return [migrate(item) for item in obj]

    if isinstance(obj, dict):
        migrated = {}

        for original_key, original_value in obj.items():
            new_key = FIELD_RENAMES.get(original_key, original_key)
            new_value = migrate(original_value)
            new_value = coerce_value(new_key, new_value)

            if new_key in migrated and original_key in FIELD_RENAMES:
                # Existing canonical key wins over legacy duplicate.
                continue

            migrated[new_key] = new_value

        return migrated

    return obj


def load_json_flexible(path: str) -> Any:
    """
    Load a normal JSON document. If that fails, make a best-effort attempt to
    load newline-delimited JSON records.

    This keeps the converter useful for closely related JSON/JSONL inputs while
    still failing clearly when nothing valid can be parsed.
    """
    with open(path, "r", encoding="utf-8") as f:
        text = f.read()

    try:
        return json.loads(text)
    except json.JSONDecodeError as original_error:
        records = []
        errors = []

        for line_number, line in enumerate(text.splitlines(), start=1):
            stripped = line.strip()

            if not stripped or stripped in {"[", "]"}:
                continue

            # Useful for files that are visually array-like but have one object
            # per line with commas.
            if stripped.endswith(","):
                stripped = stripped[:-1].rstrip()

            try:
                records.append(json.loads(stripped))
            except json.JSONDecodeError as line_error:
                errors.append((line_number, line_error))

        if records:
            if errors:
                print(
                    f"Warning: skipped {len(errors)} malformed line(s) while "
                    f"parsing as JSON Lines.",
                    file=sys.stderr,
                )
            return records

        raise original_error


def main() -> int:
    if len(sys.argv) != 3:
        print(
            f"Usage: {sys.argv[0]} SOURCE_JSON_PATH OUTPUT_JSON_PATH",
            file=sys.stderr,
        )
        return 2

    source_path = sys.argv[1]
    output_path = sys.argv[2]

    try:
        data = load_json_flexible(source_path)
        converted = migrate(data)

        with open(output_path, "w", encoding="utf-8") as f:
            json.dump(converted, f, ensure_ascii=False, indent=2)
            f.write("\n")

    except Exception as exc:
        print(f"Error converting JSON: {exc}", file=sys.stderr)
        return 1

    return 0


if __name__ == "__main__":
    raise SystemExit(main())
